[
  {
    "claim": "O103 | 5 / 20 | 200 | 15 | 5 × 45 = 225",
    "problem": "方案1部分发货时，O103可送达件数计算错误。库存A共35件，O101优先分配30件后，剩余5件给O103，缺口=20-5=15件，这部分正确。但等待48小时后到货20件，O103缺口15件可由到货补足，因此方案1中O103最终可完成，不存在永久缺口。答案将"立即可发5件"误作"最终送达5件"，混淆了两个时间点。",
    "expected": "方案1应说明：立即发O101全部30件（库存35-30=5件剩余），O103先发5件，48小时后补发剩余15件（到货20件足够）；最终O103也能完成，缺口为0，毛利=20×45=900元，与方案2相同，差异在于O103需两次发货及额外运费。"
  },
  {
    "claim": "发货时已获毛利 | 1 575 (方案 1)",
    "problem": "基于错误的"O103仅发5件"计算得出1575元，实际方案1最终毛利与方案2相同（均为2250元），差异仅在时间和运费上。",
    "expected": "方案1最终毛利=2250元，与方案2一致；若仅计算第一批发货时的即时毛利，应明确说明是"第一批"而非"最终"。"
  },
  {
    "claim": "O103 缺货导致续单失误、客户流失",
    "problem": "答案在方案1风险栏写"O103缺货"，但实际上方案1下O103并无永久缺口（48小时后到货可补），此表述具有误导性。",
    "expected": "方案1的真实风险是O103需分两次发货、客户体验分裂，而非永久缺货。"
  },
  {
    "claim": "运营交接摘要 – 订单 O101（30件）与 O103（20件）对比两种发货方案",
    "problem": "任务要求"逐单计算"，O102（SKU B，12件，迟发4小时，金额3600元）完全未被分析。O102迟发4小时未超过24小时门槛，无补偿，但仍需在逐单分析中明确说明。",
    "expected": "应包含O102的分析：迟发4小时<24小时，无补偿；库存B=20件≥12件，可正常发货；毛利=12×80=960元；两方案对O102无差异。"
  }
]

