    "claim": "C21 | 18000 | 18000 – 2000 = 16000 | 90% | 16000 × 0.9 = 14400\nC22 | 9000 | 9000 – 2000 = 7000 | 90% | 7000 × 0.9 = 6300\nC23 | 18000 | 18000 – 2000 = 16000 | 90% | 16000 × 0.9 = 14400",
    "problem": "政策明确"同一事故免赔额只扣一次"，答案对三份报案各自扣除2000元免赔额，违反政策约束。",
    "expected": "免赔额2000元仅在整体计算中扣除一次，不应对每份报案单独扣除。"
  },
  {
    "claim": "C23 … 可进入初审金额 … 16000 × 0.9 = 14400",
    "problem": "C23的票据I21与C21重复，政策要求"先去重票据"，C23应被排除，不应计算其初审金额。",
    "expected": "C23因重复票据应排除，不纳入初审计算。"
  },
  {
    "claim": "C22 … 可进入初审金额 … 7000 × 0.9 = 6300",
    "problem": "C22缺失照片证明，政策规定"缺失材料部分暂不纳入"，答案却为其计算了初审金额6300元。",
    "expected": "C22因缺失材料暂不纳入初审，不应计算初审金额。"
  },
  {
    "claim": "扣除重复后 31000 元，仍低于保单限额 30000 元（扣除重复后 21000 元）",
    "problem": "31000元高于限额30000元，与"仍低于保单限额"的表述矛盾；且同一段落前后给出31000和21000两个不同数字，自相矛盾。",
    "expected": "去重后有效金额为C21(18000)+C22(9000)=27000元，低于限额30000元；表述应一致。"
  },
  {
    "claim": "对符合条件的报案（C21、C23）按 14400 元额度继续审核流程",
    "problem": "C23为重复票据应排除，不应列为"符合条件的报案"进入审核流程。",
    "expected": "符合条件进入初审的仅为C21，当前可审金额14400元。"
  }
]

